  5	namespace Application\Bootstrap\Screen;
  6	
  7	use Application\Application;
  8	use Application\AppFactory;
  9	use Application\Bootstrap\BootException;
 10	use Application\ConfigSettings\BaseConfigRegistry;
 11	use Application_Bootstrap_Screen;
 12	use AppUtils\FileHelper;
 13	use DBHelper;
 14	
 15	class TestSuiteBootstrap extends Application_Bootstrap_Screen
 16	{
 17	    // Thrown when system users are missing from the test database; run "composer seed-tests" to seed them.
 18	    public const int ERROR_TEST_DB_NOT_SEEDED = 175001;
 19	
 20	    protected function _boot() : void
 21	    {
 22	        $this->disableAuthentication();
 23	        $this->enableScriptMode();
 24	
 25	        $this->createEnvironment();
 26	
 27	        if (!defined('APP_TESTS_RUNNING')) {
 28	            define('APP_TESTS_RUNNING', true);
 29	        }
 30	
 31	        $this->configureDatabase();
 32	        $this->registerTransactionCleanupHandler();
 33	        $this->configurePaths();
 34	        $this->configureUsers();
 35	    }
 36	
 37	    private function configureDatabase(): void
 38	    {
 39	        $port = 0;
 40	
 41	        if (defined('APP_DB_TESTS_PORT')) {
 42	            $port = (int)APP_DB_TESTS_PORT;
 43	        }
 44	
 45	        DBHelper::registerDB(
 46	            'tests',
 47	            APP_DB_TESTS_NAME,
 48	            APP_DB_TESTS_USER,
 49	            APP_DB_TESTS_PASSWORD,
 50	            APP_DB_TESTS_HOST,
 51	            $port
 52	        );
 53	
 54	        DBHelper::selectDB('tests');
 55	    }
 56	
 57	    private function configureUsers(): void
 58	    {
 59	        $users = AppFactory::createUsers();
 60	        $missingIDs = array();
 61	
 62	        foreach(Application::getSystemUserIDs() as $id)
 63	        {
 64	            if(!$users->idExists($id))
 65	            {
 66	                $missingIDs[] = $id;
 67	            }
 68	        }
 69	
 70	        if(!empty($missingIDs))
 71	        {
 72	            throw new BootException(
 73	                'Test database not seeded: system user(s) missing.',
 74	                sprintf(
 75	                    'The following system user IDs are missing from the test database: [%s]. '.
 76	                    'Run "composer seed-tests" to initialize the test environment.',
 77	                    implode(', ', $missingIDs)
 78	                ),
 79	                self::ERROR_TEST_DB_NOT_SEEDED
 80	            );
 81	        }
 82	
 83	        $this->log('System users verified.');
 84	    }
 85	
 86	    /**
 87	     * Seeds system users into the test database within a transaction.
 88	     *
 89	     * Starts a database transaction, runs the {@see InitSystemUsers} installer
 90	     * task, and commits on success. On any failure the transaction is rolled
 91	     * back via {@see DBHelper::rollbackConditional()} and the original
 92	     * throwable is re-thrown.
 93	     *
 94	     * Invoke this method via the Composer helper before running the test suite:
 95	     *
 96	     * <pre>composer seed-tests</pre>
 97	     *
 98	     * @return void
 99	     * @throws \Application_Exception If the {@see InitSystemUsers} task ID is
100	     *                                not found in the installer task registry.

101	     * @throws \Throwable             Re-throws any exception or error raised
102	     *                                during task execution after rolling back
103	     *                                the transaction.
104	     */
105	    public static function seedSystemUsers(): void
106	    {
107	        DBHelper::startTransaction();
108	
109	        try
110	        {
111	            Application::createInstaller()
112	                ->getTaskByID('InitSystemUsers')
113	                ->process();
114	
115	            DBHelper::commitTransaction();
116	        }
117	        catch(\Throwable $e)
118	        {
119	            DBHelper::rollbackConditional();
120	            throw $e;
121	        }
122	    }
123	
124	    /**
125	     * Registers a PHP shutdown handler to roll back any open transaction if
126	     * the process exits unexpectedly. Called before {@see configurePaths()} so
127	     * that even a fatal error during path setup cannot leave the database in a
128	     * partially-modified state.
129	     */
130	    private function registerTransactionCleanupHandler(): void
131	    {
132	        register_shutdown_function(static function(): void {
133	            DBHelper::rollbackConditional();
134	        });
135	    }
136	
137	    private function configurePaths(): void
138	    {
139	        $testsRoot = APP_ROOT . '/tests';
140	
141	        if (BaseConfigRegistry::areUnitTestsRunning()) {
142	            $testsRoot = APP_ROOT;
143	        }
144	
145	        if (!is_dir($testsRoot)) {
146	            die('Cannot run tests: Could not find the application\'s [tests] folder.');
147	        }
148	
149	        define('TESTS_ASSETS_FOLDER', TESTS_ROOT . '/assets');
150	        define('TESTS_CLASSES_FOLDER', TESTS_ASSETS_FOLDER . '/classes');
151	
152	        if (is_dir(TESTS_CLASSES_FOLDER)) {
153	            $names = FileHelper::createFileFinder(TESTS_CLASSES_FOLDER)
154	                ->getPHPClassNames();
155	
156	            // load all classes that may be needed for the tests to run.
157	            foreach ($names as $name) {
158	                require_once TESTS_CLASSES_FOLDER . '/' . $name . '.php';
159	            }
160	        }

